begin; select plan(32);
select has_table('public','tkid_sources','TKID sources exist');
select has_table('public','tkid_journeys','TKID Journeys exist');
select has_table('public','tkid_browser_sessions','TKID browser sessions exist');
select has_table('public','tkid_checkout_sessions','TKID checkout sessions exist');
select has_table('public','tkid_event_evidence','TKID bounded Evidence exists');
select has_table('public','tkid_events','TKID normalized events exist');
select has_table('public','tkid_commerce_links','TKID Commerce links exist');
select has_table('public','tkid_handoffs','TKID handoffs exist');
select has_column('public','tkid_events','schema_version','event schema version is persisted');
select has_column('public','tkid_events','normalizer_version','normalizer version is persisted');
select has_column('public','tkid_events','offer_version_id','offer version is persisted');
select has_column('public','tkid_events','price_amount','displayed price is persisted');
select has_column('public','tkid_events','disclosure_version','disclosure version is persisted');
select has_column('public','tkid_events','displayed_descriptor','displayed descriptor is persisted');
select has_column('public','tkid_commerce_links','parent_charge_reference','parent charge is explicit');

insert into public.tracekit_accounts(id,account_type,name) values('b5100000-0000-0000-0000-000000000001','client','TKID Account A'),('b5100000-0000-0000-0000-000000000011','client','TKID Account B');
insert into public.tracekit_organizations(id,owning_account_id,name) values('b5100000-0000-0000-0000-000000000002','b5100000-0000-0000-0000-000000000001','TKID Org A'),('b5100000-0000-0000-0000-000000000012','b5100000-0000-0000-0000-000000000011','TKID Org B');
insert into public.tracekit_business_contexts(id,account_id,organization_id,name) values('tkid-context-a','b5100000-0000-0000-0000-000000000001','b5100000-0000-0000-0000-000000000002','TKID Context A'),('tkid-context-b','b5100000-0000-0000-0000-000000000011','b5100000-0000-0000-0000-000000000012','TKID Context B');
insert into public.tkid_sources(id,account_id,organization_id,business_context_id,public_source_id,status,allowed_origins) values('b5100000-0000-4000-8000-000000000003','b5100000-0000-0000-0000-000000000001','b5100000-0000-0000-0000-000000000002','tkid-context-a','tksrc_abcdefghijklmnop','active',array['https://shop.example']);
select lives_ok($sql$insert into public.tkid_journeys(id,account_id,organization_id,business_context_id,source_id,started_at,expires_at,privacy_mode,source_version,normalizer_version) values('b5100000-0000-4000-8000-000000000004','b5100000-0000-0000-0000-000000000001','b5100000-0000-0000-0000-000000000002','tkid-context-a','b5100000-0000-4000-8000-000000000003',now(),now()+interval '2 hours','essential','sdk-v1','normalizer-v1')$sql$,'same-tenant Journey persists');
select throws_ok($sql$insert into public.tkid_journeys(id,account_id,organization_id,business_context_id,source_id,started_at,expires_at,privacy_mode,source_version,normalizer_version) values('b5100000-0000-4000-8000-000000000014','b5100000-0000-0000-0000-000000000011','b5100000-0000-0000-0000-000000000012','tkid-context-b','b5100000-0000-4000-8000-000000000003',now(),now()+interval '2 hours','essential','sdk-v1','normalizer-v1')$sql$,'23503',null,'cross-tenant source spoofing fails');
insert into public.tkid_browser_sessions(id,organization_id,journey_id,source_id,started_at,last_seen_at,expires_at) values('b5100000-0000-4000-8000-000000000005','b5100000-0000-0000-0000-000000000002','b5100000-0000-4000-8000-000000000004','b5100000-0000-4000-8000-000000000003',now(),now(),now()+interval '30 minutes');
insert into public.tkid_checkout_sessions(id,organization_id,journey_id,browser_session_id,source_id,started_at) values('b5100000-0000-4000-8000-000000000006','b5100000-0000-0000-0000-000000000002','b5100000-0000-4000-8000-000000000004','b5100000-0000-4000-8000-000000000005','b5100000-0000-4000-8000-000000000003',now());
insert into public.tkid_event_evidence(id,organization_id,source_id,event_id,evidence_hash,schema_version,bounded_payload) values('b5100000-0000-4000-8000-000000000007','b5100000-0000-0000-0000-000000000002','b5100000-0000-4000-8000-000000000003','b5100000-0000-4000-8000-000000000008',repeat('a',64),1,'{"offer_id":"oto2"}');
select lives_ok($sql$insert into public.tkid_events(id,organization_id,journey_id,browser_session_id,checkout_session_id,source_id,evidence_id,event_name,schema_version,normalizer_version,occurred_at,received_at,offer_id,offer_version_id,price_amount,currency,recurring,privacy_mode) values('b5100000-0000-4000-8000-000000000008','b5100000-0000-0000-0000-000000000002','b5100000-0000-4000-8000-000000000004','b5100000-0000-4000-8000-000000000005','b5100000-0000-4000-8000-000000000006','b5100000-0000-4000-8000-000000000003','b5100000-0000-4000-8000-000000000007','upsell_viewed',1,'normalizer-v1',now(),now(),'oto2','oto2-v1',299,'USD',false,'essential')$sql$,'bounded OTO2 event persists');
select lives_ok($sql$insert into public.tkid_commerce_links(organization_id,journey_id,checkout_session_id,charge_reference,parent_charge_reference,sequence_position,relationship) values('b5100000-0000-0000-0000-000000000002','b5100000-0000-4000-8000-000000000004','b5100000-0000-4000-8000-000000000006','synthetic-main',null,0,'main'),('b5100000-0000-0000-0000-000000000002','b5100000-0000-4000-8000-000000000004','b5100000-0000-4000-8000-000000000006','synthetic-oto2','synthetic-main',2,'upsell')$sql$,'server-authoritative parent and child charges persist');
select is((select parent_charge_reference from public.tkid_commerce_links where charge_reference='synthetic-oto2'),'synthetic-main','OTO2 child points to main charge');
select is((select provenance from public.tkid_commerce_links where charge_reference='synthetic-oto2'),'tkid_direct','prospective deterministic provenance is explicit');
select throws_ok($sql$insert into public.tkid_events(id,organization_id,journey_id,browser_session_id,source_id,evidence_id,event_name,schema_version,normalizer_version,occurred_at,received_at,privacy_mode) values(gen_random_uuid(),'b5100000-0000-0000-0000-000000000002','b5100000-0000-4000-8000-000000000004','b5100000-0000-4000-8000-000000000005','b5100000-0000-4000-8000-000000000003','b5100000-0000-4000-8000-000000000007','keypress',1,'normalizer-v1',now(),now(),'essential')$sql$,'23514',null,'unknown event is rejected');
select throws_ok($sql$insert into public.tkid_event_evidence(organization_id,source_id,event_id,evidence_hash,schema_version,bounded_payload) values('b5100000-0000-0000-0000-000000000002','b5100000-0000-4000-8000-000000000003','b5100000-0000-4000-8000-000000000008',repeat('b',64),1,'{}')$sql$,'23505',null,'event retry cannot duplicate Evidence');
select ok((select relrowsecurity from pg_class where oid='public.tkid_events'::regclass),'raw TKID events use RLS');
select ok((select relrowsecurity from pg_class where oid='public.tkid_event_evidence'::regclass),'TKID Evidence uses RLS');
select is((select count(*)::integer from information_schema.role_table_grants where table_schema='public' and table_name like 'tkid_%' and grantee in('anon','authenticated')),0,'browser roles receive no raw-table grants');
select is((select count(*)::integer from public.commerce_repository_activation),0,'TKID migration activates no Workspace repository');
select throws_ok($sql$insert into public.tkid_sources(account_id,organization_id,business_context_id,public_source_id,status,allowed_origins) values('b5100000-0000-0000-0000-000000000001','b5100000-0000-0000-0000-000000000002','tkid-context-a','source-with-semantics','active',array['https://shop.example'])$sql$,'23514',null,'source identifiers must use opaque public format');
select throws_ok($sql$insert into public.tkid_sources(account_id,organization_id,business_context_id,public_source_id,status,allowed_origins) values('b5100000-0000-0000-0000-000000000001','b5100000-0000-0000-0000-000000000002','tkid-context-a','tksrc_qrstuvwxyzabcdef','active',array[]::text[])$sql$,'23514',null,'source must have approved origins');
select throws_ok($sql$insert into public.tkid_events(id,organization_id,journey_id,browser_session_id,source_id,evidence_id,event_name,schema_version,normalizer_version,occurred_at,received_at,currency,privacy_mode) values(gen_random_uuid(),'b5100000-0000-0000-0000-000000000002','b5100000-0000-4000-8000-000000000004','b5100000-0000-4000-8000-000000000005','b5100000-0000-4000-8000-000000000003','b5100000-0000-4000-8000-000000000007','page_viewed',1,'normalizer-v1',now(),now(),'usd','essential')$sql$,'23514',null,'invalid currency fails closed');
select is((select count(*)::integer from public.tkid_events),1,'only valid normalized event exists');
select is((select count(*)::integer from public.tkid_commerce_links),2,'only explicit server fixture creates Commerce links');
select * from finish(); rollback;
